{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Tiopronin, a small N-acyl glycine with a free carboxylic acid, has absolute oral bioavailability of 63% in healthy subjects, demonstrating that a glycine-carboxylic acid amide motif can be well absorbed; this supports high F for the query's similar glycine acid side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Trocade, a cyclic urea/hydantoin MMP inhibitor bearing cycloalkyl substituents and a polar zinc-binding group, has absolute oral bioavailability of 43% in healthy volunteers; its structural similarity to the query's barbiturate/cyclic imide core with two cyclohexyl groups supports F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Omapatrilat, a lipophilic free-acid peptidomimetic with multiple amide bonds, has absolute oral bioavailability of 31% in healthy male subjects, supporting that the query's lipophilic acid/amide scaffold can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Inogatran, a peptidomimetic thrombin inhibitor containing a cyclohexyl group and a glycine carboxylic acid, has oral bioavailability <5% in healthy volunteers; this is a counterexample, but its strongly basic guanidine group and peptide-like backbone reduce transferability to the non-basic barbiturate query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Alvimopan, which shares the C(=O)NCC(=O)O glycine-acid motif and lipophilic substituents, has only 6% oral bioavailability in humans; however, its zwitterionic character and intentional design for low systemic absorption limit its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, especially from cyclic imide/urea and lipophilic free-acid analogues (Trocade 43%, omapatrilat 31%, tiopronin 63%), supports F ≥20%; the low-F counterexamples (inogatran, alvimopan) are less transferable because they contain basic/zwitterionic groups absent in the query.",
  "evidence_gaps": [
    "No direct human PK data for the query molecule.",
    "Morgan similarities to all evidence molecules are low, limiting quantitative transferability.",
    "No permeability, efflux, or solubility data are available for the query.",
    "Uncertainty remains about dissolution of the highly lipophilic dicyclohexyl barbiturate core."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

